  await page.locator('#project-catalog').waitFor({ state: 'visible' })
  await page.getByRole('button', { name: '收起目录' }).click()
  await page.getByRole('link', { name: '交付结果', exact: true }).click()
  await page.locator('#project-outcomes').waitFor({ state: 'visible' })
  for (const id of [5, 6, 7, 8, 9]) {
    await page.goto(origin + `/experience/2/projects/${id}`)
    await page.locator('#project-work li').first().waitFor()
    assert.ok((await page.locator('#project-story').innerText()).length > 1000)
    assert.ok(await page.locator('#project-story img').count() > 0, `gallery missing ${id}`)
    await noOverflow()
  }
  await page.goto(origin + '/experience/2')
  await page.locator('.project-grid a').first().waitFor()
  await screenshot('company-mobile')
  await noOverflow()
  await page.setViewportSize({ width: 768, height: 1024 })
  await noOverflow()
  await page.goto(origin + '/experience/1')
  await page.locator('.case-hero h1').waitFor()
  assert.ok((await page.locator('.case-hero h1').innerText()).includes('华安'))
  await noOverflow()
  const denied = await page.request.post(origin + '/api/experience/2/projects/back/add', { data: {} })
  assert.equal(denied.status(), 403)
  const hidden = await page.request.get(origin + '/api/user/back/list')
  assert.equal(hidden.status(), 403)
  await page.route('**/api/experience/2/projects/4', route => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, data: { id: 4, experienceId: 2, projectName: '兼容旧数据', contributions: '参与前后端开发', content: '没有目录的正文', summary: '旧记录没有封面和日期' } }) }))
  await page.goto(origin + '/experience/2/projects/4')
  await page.getByRole('heading', { name: '兼容旧数据' }).waitFor()
  assert.equal(await page.locator('.catalog-toggle').count(), 0)
  assert.equal(await page.locator('.hero .cover').count(), 0)
