  await noOverflow()
  await page.unroute('**/api/experience/2/projects/4')
  await page.route('**/api/experience/2/projects/4', route => route.fulfill({ status: 500, contentType: 'application/json', body: '{}' }))
  await page.goto(origin + '/experience/2/projects/4')
  await page.getByRole('heading', { name: '项目暂时无法查看' }).waitFor()
  assert.equal(await page.locator('#project-work').count(), 0)
  assert.deepEqual(errors, [])
  console.log('PASS: six projects, gallery preservation, desktop/mobile/tablet, dark visual, navigation, legacy data, errors, read-only preview')
